    rect_fill(VW/2+92, fy, 130, 13, G.menu_sel==n+1? COL(70,80,110):COL(44,46,66));
    rect_line(VW/2+92, fy, 130, 13, G.menu_sel==n+1? COL(255,205,40):COL(140,150,180));
